package com.cataclysm.classplugin.command;import org.bukkit.command.*;import org.bukkit.entity.Player;import com.cataclysm.classplugin.CataclysmClassPlugin;import com.cataclysm.classplugin.manager.ClassManager;public class AdminCommand implements CommandExecutor{final CataclysmClassPlugin p;final ClassManager c;public AdminCommand(CataclysmClassPlugin p,ClassManager c){this.p=p;this.c=c;}public boolean onCommand(CommandSender s,Command x,String l,String[] a){if(a.length==0)return false;if(a[0].equalsIgnoreCase("reload")){p.reloadConfig();c.reload();s.sendMessage("§aReloaded.");return true;}if(a.length<2)return false;Player t=p.getServer().getPlayerExact(a[1]);if(t==null){s.sendMessage("§cPlayer not found.");return true;}if(a[0].equalsIgnoreCase("reset")){c.reset(t);s.sendMessage("§aReset.");}else if(a[0].equalsIgnoreCase("info"))s.sendMessage("§eClass: §f"+c.get(t));return true;}}
